import {contextFixtures,moduleRegistry} from './context.js';
import {runtime,api,syncEncounter,saveBody} from './api.js';
import {generateDraft,isCurrent,canApprove,approvedCurrent,updateSource,updateItem,approve,exportPayload,noteText,status,uid} from './core.js';
import {freshFixtures} from './fixtures.js';
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={leaf:'<path d="M20 4c0 9-3 15-10 15-5 0-7-7-3-10 3-3 8-4 13-5Z"/><path d="m5 21 9-10"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',mic:'<rect x="9" y="2" width="6" height="13" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3m-4 0h8"/>',file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8Z"/><path d="M14 2v6h6M8 13h8m-8 4h6"/>',check:'<path d="m5 12 4 4L19 6"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',plus:'<path d="M12 4v16M4 12h16"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',link:'<path d="m10 13 4-4M8 16l-1 1a4 4 0 0 1-6-6l4-4a4 4 0 0 1 6 0m2 1 1-1a4 4 0 0 1 6 6l-4 4a4 4 0 0 1-6 0"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 17v4h16v-4"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',upload:'<path d="M12 17V3m-4 4 4-4 4 4M4 16v5h16v-5"/>',shield:'<path d="m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6Z"/><path d="m8 12 3 3 5-6"/>',layers:'<path d="m12 3 10 6-10 6L2 9Zm-9 11 9 5 9-5M3 18l9 5 9-5"/>'};
const icon=n=>`<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.file}</svg>`;
const KEY='clinicnote-demo-v2';let model;try{model=JSON.parse(localStorage.getItem(KEY))}catch{}if(!model?.encounters?.length){model={encounters:freshFixtures(),activeId:'visit-avery'};model.encounters[0].draft=generateDraft(model.encounters[0]);model.encounters[2].draft=generateDraft(model.encounters[2]);}
const captureScratch=new Map();
let pipeline=[],engineChoice='rules',activeJob=null;
let activeView='review',selectedSource=null,showAllSources=false,embedded=false,busy=false,search='',recorder=null,stream=null,recordingEncounter=null,audio=new Map(),toastTimer;
const current=()=>model.encounters.find(e=>e.id===model.activeId)||model.encounters[0];
function save(){try{localStorage.setItem(KEY,JSON.stringify(model))}catch{toast('Browser storage is unavailable. Download your approved demo note before leaving.')}}
function audit(e,action){e.audit.unshift({at:new Date().toISOString(),action});save()}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3800)}
function pill(e){let t=status(e);return `<span class="pill ${t==='Approved'?'green':t==='Needs clarification'||t==='Needs refresh'?'amber':'neutral'}"><i></i>${esc(t)}</span>`}
function render(){const e=current(),draft=e.draft,currentDraft=isCurrent(e),approved=approvedCurrent(e),needs=draft?.issues.filter(i=>i.blocking)||[];document.body.classList.toggle('embedded',embedded);
$('#app').innerHTML=`${embedded?`<div class="host-preview"><span>${icon('layers')} Illustrative clinic workspace</span><strong>Encounter / ${esc(e.patient.recordId)} / Documentation</strong><button data-action="embed">Exit workspace preview ${icon('close')}</button></div>`:''}<div class="app-shell"><aside class="rail"><a href="#" class="wordmark" data-action="home"><span class="logo">${icon('leaf')}</span><strong>ClinicNote<span>Connected care workspace</span></strong></a><div class="rail-label">CARE WORKSPACE</div><button class="nav-item" data-action="tab" data-tab="context">${icon('layers')} Patient context</button><button class="nav-item" data-action="tab" data-tab="tasks">${icon('check')} Care tasks</button><button class="nav-item active" data-action="home">${icon('grid')} Encounters <span>${model.encounters.length}</span></button><button class="nav-item" data-action="platform">${icon('shield')} Platform & models</button><button class="nav-item" data-action="about">${icon('layers')} Product & integration</button><div class="rail-bottom"><div class="demo-indicator"><span></span> Synthetic demo</div><p>Built for preventive primary care.</p><button class="nav-item small" data-action="reset">Reset demo</button><div class="clinician"><span class="avatar">DC</span><div><strong>Demo clinician</strong><small>Local prototype session</small></div></div></div></aside><div class="main-shell"><header class="topbar"><span class="breadcrumbs">Clinic workspace <span>/</span> Encounter notes</span><div class="topbar-actions"><button class="quiet" data-action="tour">${icon('info')} Demo guide</button><button class="quiet" data-action="embed">${icon('layers')} Workspace preview</button><span class="runtime-badge">${runtime.connected?'Local backend · connected':'Private synthetic preview'}</span></div></header><div class="intro"><div><div class="eyebrow">A CLEARER PICTURE. A REVIEWABLE NEXT STEP.</div><h1>One patient. Connected context.</h1><p>Today’s encounter, its evidence, and the history around it. Physician review stays at the center.</p></div><button class="primary" data-action="new">${icon('plus')} New encounter</button></div><div class="workspace-layout"><aside class="worklist"><div class="worklist-head"><div><h2>Clinic worklist</h2><span>${model.encounters.length} fictional encounters</span></div>${icon('clock')}</div><label class="sr-only" for="visit-search">Find an encounter</label><input id="visit-search" type="search" placeholder="Find a patient or visit…" value="${esc(search)}"><div class="encounter-list">${model.encounters.filter(v=>(v.patient.name+' '+v.reason).toLowerCase().includes(search.toLowerCase())).map(v=>`<button class="encounter ${v.id===e.id?'selected':''}" data-action="select" data-id="${esc(v.id)}"><div class="encounter-top"><span class="patient-avatar ${v.accent||'sage'}">${esc(v.patient.initials)}</span><span class="encounter-time">${esc(v.time)}</span></div><strong>${esc(v.patient.name)}</strong><span class="visit-reason">${esc(v.reason)}</span><small>${esc(v.visitType)}</small>${pill(v)}</button>`).join('')||'<p class="empty-list">No matching encounters.</p>'}</div><div class="worklist-note">${icon('shield')}<p>Only fictional information belongs in this prototype.</p></div></aside><section id="workspace" class="workspace" aria-label="Active encounter"><header class="encounter-header"><div class="patient-avatar large ${e.accent||'sage'}">${esc(e.patient.initials)}</div><div class="patient-heading"><div class="name-row"><h2>${esc(e.patient.name)}</h2>${pill(e)}</div><p>${e.patient.age?esc(e.patient.age)+' years · ':''}${esc(e.patient.recordId)} · ${esc(e.visitType)}</p></div><button class="icon-button" data-action="history" aria-label="View encounter history">${icon('clock')}</button></header><div class="encounter-meta"><span>${esc(e.reason)}</span><span>${esc(e.date)} · ${esc(e.time)}</span></div><div class="patient-context-strip"><span>${icon('layers')} ${(contextFixtures[e.id]||[]).length} sample background records</span><button data-action="tab" data-tab="context">View patient context ${icon('arrow')}</button><small>Not included in today’s draft</small></div><div class="workspace-tabs" role="tablist" aria-label="Encounter views"><button role="tab" aria-selected="${activeView==='capture'}" data-action="tab" data-tab="capture">${icon('mic')} Capture</button><button role="tab" aria-selected="${activeView==='review'}" data-action="tab" data-tab="review">${icon('file')} Review note ${draft?'<span class="tiny-count">1</span>':''}</button><button role="tab" aria-selected="${activeView==='context'}" data-action="tab" data-tab="context">${icon('layers')} Background</button><button role="tab" aria-selected="${activeView==='tasks'}" data-action="tab" data-tab="tasks">${icon('check')} Tasks</button><button role="tab" aria-selected="${activeView==='export'}" data-action="tab" data-tab="export">${icon('download')} Export</button></div><div class="workspace-body">${busy?processingView():activeView==='capture'?captureView(e):activeView==='export'?exportView(e):activeView==='context'?contextView(e):activeView==='tasks'?tasksView(e):reviewView(e)}</div></section></div><footer class="app-footer"><span>Independent prototype · synthetic examples · ${runtime.connected?'local API + SQLite':'device-local preview'}</span><button data-action="about">What is live in this demo? ${icon('arrow')}</button></footer></div></div>`;
wireInputs();if(e.draft&&isCurrent(e)&&activeView==='review'&&!busy)wireEditors(e);
}
function processingView(){return `<div class="processing"><div class="processing-orbit"><span></span><span></span><span></span></div><p class="eyebrow">DOCUMENTATION PIPELINE</p><h3>Preparing a draft you can inspect.</h3><p>${runtime.connected?'Durable local job · actual stage events':'On-device source renderer · no remote model call'}</p><ol>${pipeline.map((x,i)=>`<li class="${i===pipeline.length-1?'current-step':'completed-step'}"><span>${i===pipeline.length-1?'…':'✓'}</span><div><strong>${esc(x.label)}</strong><small>${x.detail||''}</small></div></li>`).join('')}</ol>${runtime.connected?'<button class="secondary" data-action="cancel-job">Cancel processing</button>':''}</div>`}

function captureView(e){const a=audio.get(e.id);return `<div class="capture-view"><div class="section-heading"><span class="eyebrow">START WITH THE ENCOUNTER</span><h3>Keep the conversation at the center.</h3><p>Record locally or upload a fictional recording, then add its matching transcript.</p></div><div class="capture-options"><button class="capture-option ${recorder?'recording':''}" data-action="record">${icon('mic')}<strong>${recorder?'Stop recording':'Record locally'}</strong><span>${recorder?'Audio stays in this tab':'Microphone permission required'}</span></button><label class="capture-option" for="audio-upload">${icon('upload')}<strong>Upload audio</strong><span>Audio file · kept in this tab</span><input id="audio-upload" type="file" accept="audio/*" hidden></label><button class="capture-option" data-action="sample">${icon('file')}<strong>Use sample visit</strong><span>Fictional, speaker-labeled transcript</span></button></div>${a?`<div class="audio-player"><div><strong>${esc(a.name)}</strong><span>${runtime.connected?'Local audio · transcription runs on this laptop':'Local audio · live transcription not connected'}</span></div><audio controls src="${esc(a.url)}"></audio>${runtime.connected?'<button class="secondary" data-action="transcribe">Transcribe locally</button>':''}<button class="quiet" data-action="remove-audio">Remove</button></div>`:''}<div class="transcript-heading"><label for="transcript-editor">Encounter transcript</label><span>Source v${e.sourceVersion}</span></div><p class="help">Use Patient: or Clinician: for each line. Explicit clinician sections use Assessment:, Plan:, or Exam:. Unclear or unknown passages require clarification.</p><textarea id="transcript-editor" class="transcript-editor" rows="12" placeholder="Patient: …&#10;Clinician: Assessment: …&#10;Clinician: Plan: …">${esc(captureScratch.get(e.id)??e.transcript)}</textarea><div class="capture-footer"><span>${icon('info')} No audio is sent to a transcription provider.</span><button class="primary" data-action="save-draft" ${recorder?'disabled':''}>Save source & prepare draft ${icon('arrow')}</button></div><button class="text-button" data-action="save-source">Save transcript only</button></div>`}
function reviewView(e){if(!e.draft)return `<div class="empty-state"><span class="empty-symbol">${icon('file')}</span><h3>A clear note starts here.</h3><p>Add a transcript to prepare the first draft for this visit.</p><button class="primary" data-action="tab" data-tab="capture">Open capture ${icon('arrow')}</button></div>`;
const d=e.draft,currentDraft=isCurrent(e),approved=approvedCurrent(e),blocking=d.issues.filter(i=>i.blocking);const sectionNames=d.template==='visit'?{subjective:'Encounter history',objective:'Documented observations',assessment:'Assessment stated by clinician',plan:'Plan stated by clinician'}:null;
return `<div class="review-toolbar"><div class="template-select"><label for="template">Note format</label><select id="template"><option value="soap" ${e.template==='soap'?'selected':''}>SOAP note</option><option value="visit" ${e.template==='visit'?'selected':''}>Visit note</option></select></div>${runtime.connected?`<label class="engine-label">Engine<select id="engine-choice"><option value="rules" ${engineChoice==='rules'?'selected':''}>Exact-source renderer</option><option value="qwen" ${engineChoice==='qwen'?'selected':''}>Qwen 4B · source audit</option></select></label>`:''}<span class="draft-meta">Draft ${d.version} · Source ${d.sourceVersion}</span><button class="quiet" data-action="regenerate">${icon('layers')} Rebuild from source</button></div>${!currentDraft?`<div class="notice amber"><strong>Source or format changed. This draft needs a refresh.</strong><p>The previous approval cannot apply to the updated visit.</p><button data-action="generate" class="primary">Prepare updated draft</button></div>`:''}${blocking.length?`<div class="notice amber"><div>${icon('info')}<strong>${blocking.length} source ${blocking.length===1?'passage needs':'passages need'} clarification</strong></div><p>These passages were left out. Resolve them in the transcript before approving.</p><button class="text-button" data-action="tab" data-tab="capture">Review transcript ${icon('arrow')}</button></div>`:''}${pipeline.length?`<details class="pipeline-receipt"><summary>${icon('check')} ${pipeline.length} processing events · view trace</summary>${pipeline.map(x=>`<p>${esc(x.label)}</p>`).join('')}</details>`:''}<div class="review-grid"><div class="note-paper"><div class="paper-heading"><div><span class="eyebrow">${approved?'REVIEWED NOTE':'DRAFT · CLINICIAN REVIEW REQUIRED'}</span><h3>${e.template==='soap'?'SOAP note':'Visit note'}</h3></div><span class="paper-mark">${icon('leaf')}</span></div><p class="paper-context">${esc(e.patient.name)} <span>·</span> ${esc(e.date)}</p>${d.sections.map(s=>`<section class="note-section"><div class="note-section-heading"><h4>${esc(sectionNames?.[s.key]||s.label)}</h4><span class="section-letter">${s.key[0].toUpperCase()}</span></div>${s.items.length?s.items.map(i=>`<div class="note-item ${i.origin==='manual'?'manual':''}"><div class="item-meta"><span>${i.origin==='manual'?'Edited by reviewer':i.role==='patient'?'Patient report':i.role==='clinician'?'Clinician stated':'Attributed statement'}${i.uncertain?' · uncertainty preserved':''}</span><button class="source-link" data-action="source" data-source="${i.sourceIds[0]}" aria-label="View source ${i.sourceIds[0]}">${icon('link')} ${i.sourceIds[0].slice(1).padStart(2,'0')}</button></div><label class="sr-only" for="edit-${i.id}">Edit ${esc(s.label)} statement ${i.sourceIds[0]}</label><textarea id="edit-${i.id}" data-item="${i.id}" class="note-editor" rows="${Math.max(2,Math.ceil(i.text.length/70))}" ${!currentDraft?'disabled':''}>${esc(i.text)}</textarea></div>`).join(''):`<p class="not-documented">Not documented in source.<span>Left open for clinician completion.</span></p>`}</section>`).join('')}<p class="paper-footnote">Drafted by deterministic demo rules from the labeled source. Clinical correctness has not been validated.</p></div><aside class="evidence-panel"><div class="evidence-header"><span>${icon('link')} Source evidence</span><button class="quiet" data-action="all-sources">${showAllSources?'Focused':'All'} sources</button></div><p class="evidence-intro">See the original wording behind a draft statement.</p>${sourceView(e)}<div class="review-checks"><h4>Review checklist</h4><div>${icon('check')} Source references resolve</div><div class="${d.issues.some(i=>i.blocking)?'attention':''}">${icon(d.issues.some(i=>i.blocking)?'info':'check')} ${d.issues.some(i=>i.blocking)?'Clarification still required':'No unresolved source markers'}</div><p>These checks verify demo structure and references. They do not establish clinical accuracy.</p><button class="text-button" data-action="tab" data-tab="capture">Correct the source ${icon('arrow')}</button></div>${e.previousDraft?'<button class="quiet full" data-action="compare">View previous draft</button>':''}</aside></div><div class="approval-bar ${approved?'approved':''}"><div class="approval-icon">${icon(approved?'check':'shield')}</div><div><strong>${approved?'Reviewed and approved':'Your review completes the note'}</strong><span>${approved?`By ${esc(d.approval.reviewer)} · applies to this version only`:'Check attribution, missing information, and your edits.'}</span></div><button class="${approved?'primary':'primary'}" data-action="${approved?'tab':'approve'}" ${approved?'data-tab="export"':''} ${!approved&&!canApprove(e)?'disabled':''}>${approved?'Continue to export':'Review & approve'} ${icon('arrow')}</button></div>`}
function sourceView(e){const spans=e.draft.spans;const chosen=spans.find(s=>s.id===selectedSource)||spans[0];const display=showAllSources?spans:chosen?[chosen]:[];return display.map(s=>`<article class="source-card ${s.id===selectedSource?'focused':''}"><div><span class="speaker ${s.role}">${esc(s.role==='clinician'?'Clinician':s.role==='patient'?'Patient':s.role==='unknown'?'Unknown speaker':s.role)}</span><span class="source-id">${s.id.toUpperCase()} · line ${s.order}</span></div><p>“${esc(s.text)}”</p><small>Transcript v${e.draft.sourceVersion} · exact source text</small></article>`).join('')}
function exportView(e){if(!approvedCurrent(e))return `<div class="empty-state"><span class="empty-symbol">${icon('shield')}</span><h3>Review first. Export with confidence.</h3><p>Approve the current draft after resolving source issues. Changes to the source or note require a fresh approval.</p><button class="primary" data-action="tab" data-tab="review">Return to review ${icon('arrow')}</button></div>`;return `<div class="export-view"><div class="success-seal">${icon('check')}</div><span class="eyebrow">REVIEW COMPLETE</span><h3>Ready for your next step.</h3><p class="export-lede">${esc(e.patient.name)}’s note is approved for this demo version.</p><div class="export-cards"><button data-action="copy" class="export-card">${icon('file')}<strong>Copy note</strong><span>Plain text for review and handoff</span>${icon('arrow')}</button><button data-action="download-text" class="export-card">${icon('download')}<strong>Download note</strong><span>A readable text file</span>${icon('arrow')}</button><button data-action="download-json" class="export-card">${icon('layers')}<strong>Download structured data</strong><span>Demo JSON with source references</span>${icon('arrow')}</button></div><div class="integration-card"><div class="connection-icon">${icon('link')}</div><div><strong>Connect within the clinic’s workflow</strong><p>Preview the note workspace inside an illustrative host. No EHR connection is active; exports stay in your browser.</p></div><button class="secondary" data-action="embed">Preview placement</button></div><div class="approval-receipt"><span>Reviewed by <strong>${esc(e.draft.approval.reviewer)}</strong></span><span>Draft ${e.draft.version} / revision ${e.draft.revision}</span><span>${e.exportCount||0} local exports</span></div></div>`}
function wireInputs(){$('#engine-choice')?.addEventListener('change',ev=>engineChoice=ev.target.value);$('#transcript-editor')?.addEventListener('input',ev=>captureScratch.set(current().id,ev.target.value));const se=$('#visit-search');se?.addEventListener('input',ev=>{search=ev.target.value;const start=ev.target.selectionStart;render();$('#visit-search').focus();$('#visit-search').setSelectionRange(start,start)});$('#template')?.addEventListener('change',ev=>{current().template=ev.target.value;audit(current(),'Note format changed; draft refresh required');render()});$('#audio-upload')?.addEventListener('change',ev=>{const f=ev.target.files[0];if(!f)return;if(f.size>50*1024*1024){toast('Choose a demo recording under 50 MB.');return;}if(!f.type.startsWith('audio/')){toast('Choose an audio file recognized by this browser.');return;}clearAudio(current().id);audio.set(current().id,{url:URL.createObjectURL(f),name:f.name,blob:f});render();toast('Audio added locally. Add its matching transcript below.');});}
function wireEditors(e){$$('.note-editor').forEach(el=>{const resize=()=>{el.style.height='auto';el.style.height=Math.max(60,el.scrollHeight+3)+'px'};resize();el.addEventListener('input',()=>{resize();if(updateItem(e,el.dataset.item,el.value)){save();const headerPill=$('.name-row .pill'),rowPill=$('.encounter.selected .pill');if(headerPill)headerPill.outerHTML=pill(e);if(rowPill)rowPill.outerHTML=pill(e);const paperLabel=$('.paper-heading .eyebrow');if(paperLabel)paperLabel.textContent='DRAFT · CLINICIAN REVIEW REQUIRED';$('.approval-bar')?.classList.remove('approved');const bar=$('.approval-bar');bar.innerHTML=`<div class="approval-icon">${icon('shield')}</div><div><strong>Edited draft needs your approval</strong><span>Your edits are reviewer-entered content.</span></div><button class="primary" data-action="approve" ${canApprove(e)?'':'disabled'}>Review & approve ${icon('arrow')}</button>`;const meta=el.closest('.note-item');meta.classList.add('manual');$('.item-meta>span',meta).textContent='Edited by reviewer';}});el.addEventListener('change',()=>audit(e,'Reviewer edited a draft statement; approval cleared'));});}
function modal(html){$('#modal-content').innerHTML=`<button class="modal-close icon-button" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button>${html}`;$('#modal').showModal()}
async function prepare(){const e=current();if(!e.transcript.trim()){toast('Add a transcript first.');return;}if(recorder){toast('Stop the local recording first.');return;}busy=true;activeView='review';pipeline=[{label:'Pinning encounter and source version'}];render();try{if(runtime.connected){await syncEncounter(e);const job=await api('/api/encounters/'+encodeURIComponent(e.id)+'/jobs',{method:'POST',body:JSON.stringify({operation_key:uid(),expected_revision:e.recordRevision,engine:engineChoice})});activeJob=job.id;let state=job;while(!['succeeded','failed','canceled'].includes(state.status)){await new Promise(r=>setTimeout(r,400));state=await api('/api/jobs/'+state.id);pipeline=state.stages.map(x=>({label:x.label}));render();}if(state.status==='canceled')throw new Error('Processing canceled. No new draft was published.');if(state.status==='failed')throw new Error(state.message);const list=await api('/api/encounters');Object.assign(e,list.encounters.find(x=>x.id===e.id));}else{await new Promise(requestAnimationFrame);pipeline.push({label:'Reading attributed source statements'});render();await new Promise(requestAnimationFrame);if(e.draft)e.previousDraft=structuredClone(e.draft);e.draft=generateDraft(e);pipeline.push({label:'Applying source, role and missing-information rules'});render();await new Promise(requestAnimationFrame);pipeline.push({label:'Draft prepared · clinician review required'});}selectedSource=null;audit(e,'Draft prepared from current source');toast('Draft ready for clinician review.');}catch(err){pipeline.push({label:'Stopped · draft not accepted'});toast(err.message);}finally{busy=false;activeJob=null;render();}}

async function approvalDialog(){const e=current();if(runtime.connected){try{await syncEncounter(e);}catch(err){toast(err.message);return;}}if(!canApprove(e)){toast('Refresh the draft and resolve source issues first.');return;}modal(`<span class="modal-eyebrow">FINAL REVIEW · SYNTHETIC DEMO</span><h2>Make this version yours.</h2><p>Review the complete note, including your edits and any sections left undocumented.</p><form id="approval-form"><label for="reviewer">Reviewer name</label><input id="reviewer" name="reviewer" value="Demo clinician" required maxlength="100"><label class="checkbox-label"><input id="review-confirm" type="checkbox" required><span>I reviewed attribution, uncertainty, omissions, and the draft text. I approve this exact version for demo export.</span></label><div class="modal-version">Draft ${e.draft.version} · revision ${e.draft.revision} · source ${e.sourceVersion}</div><button class="primary full" type="submit">Approve current note ${icon('check')}</button></form>`);$('#approval-form').addEventListener('submit',async ev=>{ev.preventDefault();if(!$('#review-confirm').checked)return;try{if(runtime.connected){Object.assign(e,await api('/api/encounters/'+e.id+'/approve',{method:'POST',body:JSON.stringify({expected_revision:e.recordRevision,draft_id:e.draft.id,revision:e.draft.revision,confirmed:true})}));}else approve(e,$('#reviewer').value);audit(e,'Explicit demo reviewer approval recorded');$('#modal').close();render();toast('Current note approved.');}catch(err){toast(err.message)}});}
function newDialog(){modal(`<span class="modal-eyebrow">START A FICTIONAL VISIT</span><h2>A new encounter.</h2><p>Use invented details only. ${runtime.connected?'Text is stored by the local API on this laptop.':'Text is stored in this browser.'}</p><form id="new-form"><label for="new-name">Fictional patient name</label><input id="new-name" required maxlength="80" placeholder="e.g. Alex Taylor"><label for="new-reason">Visit reason</label><input id="new-reason" required maxlength="140" placeholder="e.g. Preventive follow-up"><label for="new-type">Visit type</label><select id="new-type"><option>Primary care · preventive follow-up</option><option>Primary care · routine follow-up</option><option>Telehealth · follow-up</option><option>Specialty clinic · follow-up</option></select><button type="submit" class="primary full">Create encounter ${icon('arrow')}</button></form>`);$('#new-form').addEventListener('submit',ev=>{ev.preventDefault();const name=$('#new-name').value.trim(),reason=$('#new-reason').value.trim();if(!name||!reason)return;const e={id:uid(),patient:{name,initials:name.split(' ').slice(0,2).map(s=>s[0]).join('').toUpperCase(),recordId:'DEMO-'+Math.random().toString(36).slice(2,6).toUpperCase()},reason,visitType:$('#new-type').value,time:new Date().toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit'}),date:new Date().toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}),transcript:'',sourceVersion:1,template:'soap',draft:null,previousDraft:null,audit:[],exportCount:0};model.encounters.push(e);model.activeId=e.id;activeView='capture';search='';audit(e,'Fictional encounter created');$('#modal').close();render()});}
function download(text,name,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function clearAudio(id){const a=audio.get(id);if(a)URL.revokeObjectURL(a.url);audio.delete(id)}
async function record(){if(recorder){recorder.stop();return;}if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('Recording is unavailable here. Upload audio or use a sample.');return;}try{stream=await navigator.mediaDevices.getUserMedia({audio:true});const id=current().id;recordingEncounter=id;const chunks=[];recorder=new MediaRecorder(stream);const mime=recorder.mimeType;recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onstop=()=>{const blob=new Blob(chunks,{type:mime});clearAudio(id);audio.set(id,{url:URL.createObjectURL(blob),name:'Local encounter recording',blob});stream.getTracks().forEach(t=>t.stop());stream=null;recorder=null;recordingEncounter=null;render();toast('Recording saved in this tab. Add the matching transcript to continue.');};recorder.start();render();}catch{if(stream)stream.getTracks().forEach(t=>t.stop());stream=null;toast('Microphone was not available. Upload audio or use a sample instead.');}}
function about(){modal(`<span class="modal-eyebrow">PRODUCT SCOPE & INTEGRATION</span><h2>A clinic visit, with a clearer finish.</h2><p>Designed around preventive primary care. Navierre publicly identifies Dr. Sakina Dinani as its co-founder, chief medical officer and a primary care physician. Her exact documentation workflow has not been confirmed.</p><div class="scope-grid"><div><h3>Working in this prototype</h3><p>Fictional worklist, local audio capture/upload, transcript editing, deterministic source-linked drafts, clarification flags, reviewer edits, version-aware approval, text/JSON export and local history.</p></div><div><h3>Integration milestones</h3><p>The local version now has speech/model adapters and persistent API state. Production identity, approved clinical evaluation, clinic templates and a verified host/EHR adapter remain integration milestones. There is no live clinical connection.</p></div></div><p>${runtime.connected?'Text and review state persist in local SQLite. Audio is processed locally only when you select transcription.':'Audio stays in the tab; text saves in this browser.'} Use fictional data. Draft rules do not establish clinical accuracy or detect every unsupported assertion.</p><div class="modal-links"><a href="PRODUCT_AND_INTEGRATION.md" target="_blank">Product, architecture & integration plan ↗</a><a href="https://www.navierre.com/about" target="_blank" rel="noreferrer">Public role reference ↗</a></div>`)}
function tour(){modal(`<span class="modal-eyebrow">A FIVE-MINUTE WALKTHROUGH</span><h2>Show the visit. Then show the value.</h2><ol class="tour-steps"><li><b>Open Avery’s note.</b> Explain that the patient reports symptoms, while the clinician’s uncertainty stays explicit.</li><li><b>Follow a source link.</b> Show the original wording without leaving the note.</li><li><b>Correct and review.</b> Edit a statement, approve this version, then copy or download it.</li><li><b>Open Riley’s visit.</b> Show that unclear audio and an unknown speaker cannot silently become facts.</li><li><b>Change the source.</b> Show the old approval becoming stale and rebuild the draft.</li></ol><p>All examples are fictional. ${runtime.connected?'Local speech and an optional Qwen source-copy audit are connected. Note wording is still rendered from verified source text.':'The hosted preview uses deterministic rendering; laptop model services are not exposed here.'}</p><button class="primary full" data-action="close-modal">Start walkthrough ${icon('arrow')}</button>`)}
document.addEventListener('click',async ev=>{const b=ev.target.closest('[data-action]');if(!b)return;if(b.tagName==='A')ev.preventDefault();if(b.disabled)return;const a=b.dataset.action,e=current();if(busy&&!['close-modal','cancel-job'].includes(a))return;
if(a==='cancel-job'){if(activeJob)await api('/api/jobs/'+activeJob+'/cancel',{method:'POST'});return;}if(a==='close-modal')$('#modal').close();else if(a==='home'){search='';render();}else if(a==='select'){if(recorder){toast('Stop the recording before changing encounters.');return;}model.activeId=b.dataset.id;activeView=current().draft?'review':'capture';selectedSource=null;showAllSources=false;save();render();}else if(a==='tab'){activeView=b.dataset.tab;if(runtime.connected&&activeView==='context'){try{e.contextRecords=(await api('/api/encounters/'+e.id+'/context')).records;}catch(err){toast(err.message)}}render();}else if(a==='new'){if(recorder){toast('Stop recording before creating a new encounter.');return;}newDialog();}else if(a==='platform')platform();else if(a==='add-task')taskDialog();else if(a==='complete-task'){const t=(e.tasks||[]).find(t=>t.id===b.dataset.id);if(t){if(runtime.connected){try{Object.assign(e,await api('/api/encounters/'+e.id+'/tasks/'+t.id,{method:'POST',body:JSON.stringify({expected_revision:e.recordRevision,completed:!t.completed})}));}catch(err){toast(err.message);return;}}else t.completed=!t.completed;}audit(e,'Clerical task status updated locally');render();}else if(a==='about')about();else if(a==='tour')tour();else if(a==='embed'){embedded=!embedded;render();}else if(a==='source'){selectedSource=b.dataset.source;showAllSources=false;render();$('.evidence-panel')?.scrollIntoView({behavior:'smooth',block:'nearest'});}else if(a==='all-sources'){showAllSources=!showAllSources;render();}else if(a==='generate')await prepare();else if(a==='save-source'||a==='save-draft'){const text=$('#transcript-editor')?.value||'';if(updateSource(e,text))audit(e,'Transcript changed; prior draft/approval now stale');captureScratch.delete(e.id);save();if(runtime.connected){try{await syncEncounter(e);}catch(err){toast(err.message);return;}}if(a==='save-draft')await prepare();else{render();toast('Transcript saved. Rebuild any existing draft before review.');}}else if(a==='regenerate'){modal(`<h2>Rebuild from the source?</h2><p>This creates a new draft version. Reviewer edits stay in the previous-version view; a fresh review will be required.</p><button class="primary full" data-action="confirm-rebuild">Rebuild draft</button>`);}else if(a==='confirm-rebuild'){$('#modal').close();await prepare();}else if(a==='approve')approvalDialog();else if(a==='history'){if(runtime.connected){try{const r=await api('/api/encounters/'+e.id+'/audit');e.audit=r.events.map(x=>({at:new Date(x.created*1000).toISOString(),action:x.action})).reverse();}catch(err){toast(err.message);return;}}modal(`<span class="modal-eyebrow">LOCAL ENCOUNTER HISTORY</span><h2>${esc(e.patient.name)}</h2><p>${runtime.connected?'Events come from the local API’s append-only event table. Database administrators remain outside this demo trust boundary.':'These events are browser-local demo records, not a clinical audit log.'}</p><div class="history-list">${e.audit.length?e.audit.map(x=>`<div><small>${new Date(x.at).toLocaleString()}</small><p>${esc(x.action)}</p></div>`).join(''):'<p>No actions recorded yet.</p>'}</div>`);}else if(a==='compare'){const d=e.previousDraft;modal(`<span class="modal-eyebrow">PREVIOUS VERSION</span><h2>Draft ${d.version} · source ${d.sourceVersion}</h2><p>Read-only prior snapshot. Approval does not apply to the current draft.</p>${d.sections.map(s=>`<h3>${esc(s.label)}</h3><p>${s.items.map(i=>esc(i.text)).join('<br>')||'Not documented.'}</p>`).join('')}`);}else if(a==='copy'||a==='download-text'||a==='download-json'){try{if(runtime.connected)await api('/api/encounters/'+e.id+'/export');const p=exportPayload(e);if(a==='copy'){if(!navigator.clipboard)throw new Error('Clipboard unavailable. Download the note instead.');await navigator.clipboard.writeText(noteText(e));}else if(a==='download-text')download(noteText(e),`${e.patient.recordId}-note.txt`,'text/plain');else download(JSON.stringify(p,null,2),`${e.patient.recordId}-note.json`,'application/json');e.exportCount++;audit(e,a==='copy'?'Approved note copied locally':'Approved note downloaded locally');render();toast(a==='copy'?'Approved note copied. No EHR message was sent.':'Approved note downloaded. No EHR message was sent.');}catch(err){toast(err.message)}}else if(a==='transcribe'){const file=audio.get(e.id)?.blob;if(!runtime.connected||!file){toast('Local audio and backend required.');return;}modal('<p class="modal-eyebrow">LOCAL SPEECH SERVICE</p><h2>Transcribing the recording…</h2><p>This is a real local request. Speaker roles will need confirmation before drafting.</p>');try{const r=await fetch('/api/transcribe',{method:'POST',credentials:'same-origin',body:file,headers:{'Content-Type':file.type||'application/octet-stream'}});const d=await r.json();if(!r.ok)throw new Error(d.detail);captureScratch.set(e.id,d.transcript);e.transcriptionSegments=d.segments;$('#modal').close();render();toast('Transcript ready. Confirm the Unknown speaker labels before drafting.');}catch(err){$('#modal').close();toast(err.message);}}else if(a==='record')await record();else if(a==='remove-audio'){clearAudio(e.id);render();}else if(a==='sample'){modal(`<h2>Load a fictional transcript</h2><p>This replaces the current transcript with Avery’s sample encounter. The patient record stays unchanged and any draft becomes stale.</p><button class="primary full" data-action="confirm-sample">Load sample transcript</button>`);}else if(a==='confirm-sample'){const sample=freshFixtures()[0].transcript;updateSource(e,sample);captureScratch.delete(e.id);audit(e,'Fictional sample transcript loaded');$('#modal').close();render();}else if(a==='reset'){modal(`<h2>Reset the synthetic demo?</h2><p>This clears browser-local demo notes, approvals, and history, and restores the three sample encounters.</p><button class="primary full" data-action="confirm-reset">Reset demo</button>`);}else if(a==='confirm-reset'){if(runtime.connected){toast('Local backend records persist. Use a separate test database to reset server state.');$('#modal').close();return;}if(recorder){toast('Stop recording before resetting.');return;}for(const id of audio.keys())clearAudio(id);captureScratch.clear();model={encounters:freshFixtures(),activeId:'visit-avery'};model.encounters[0].draft=generateDraft(model.encounters[0]);model.encounters[2].draft=generateDraft(model.encounters[2]);activeView='review';selectedSource=null;search='';save();$('#modal').close();render();toast('Demo restored.');}
});
$('#modal').addEventListener('click',ev=>{if(ev.target===$('#modal'))$('#modal').close()});
window.addEventListener('beforeunload',()=>{if(stream)stream.getTracks().forEach(t=>t.stop());for(const id of audio.keys())clearAudio(id)});
async function bootstrap(){if(!['127.0.0.1','localhost'].includes(location.hostname)||location.port!=='8784'){render();return;}try{runtime.health=await api('/api/health');runtime.connected=true;let remote=await api('/api/encounters');if(!remote.encounters.length){for(const e of freshFixtures())await api('/api/encounters/'+e.id,{method:'POST',body:JSON.stringify(saveBody(e))});remote=await api('/api/encounters');}model={encounters:remote.encounters,activeId:remote.encounters[0].id};}catch{}render();}bootstrap();

function contextView(e){const records=e.contextRecords??contextFixtures[e.id]??[];return `<div class="context-view"><p class="eyebrow">PATIENT CONTEXT · SYNTHETIC RECORDS</p><h3>The history around today’s visit.</h3><p class="context-lede">Dated sources stay separate from the current encounter. No historical information is silently copied into today’s assessment or plan.</p><div class="context-summary"><div><b>${records.length}</b><span>Background records</span></div><div><b>Current visit</b><span>Only source used for this note</span></div><div><b>Review required</b><span>Historical entries are not new findings</span></div></div><div class="context-timeline">${records.map(r=>`<article><div class="timeline-dot"></div><div class="record-meta"><time>${esc(r.date)}</time><span>${esc(r.kind)}</span><span class="pill">${esc(r.status)}</span></div><h4>${esc(r.title)}</h4><p>${esc(r.text)}</p><small>${esc(r.source)} · ${esc(r.id)} · sample record</small></article>`).join('')||'<p>No background records are attached to this fictional encounter.</p>'}</div><div class="context-boundary">${icon('shield')} History access and current-note generation are separate boundaries. A live longitudinal data connector has not been attached.</div></div>`}
function tasksView(e){return `<div class="context-view"><p class="eyebrow">CARE COORDINATION · LOCAL DEMO</p><h3>Keep the follow-through visible.</h3><p class="context-lede">Reviewer-entered administrative tasks only. This board sends no messages, prescriptions, orders or appointments.</p><button class="primary" data-action="add-task">${icon('plus')} Add a clerical task</button><div class="tasks-list">${(e.tasks||[]).map(t=>`<article><div><strong>${esc(t.title)}</strong><span>Entered by demo reviewer · ${t.completed?'Completed':'Pending'}</span></div><button class="secondary" data-action="complete-task" data-id="${t.id}">${t.completed?'Reopen':'Mark complete'}</button></article>`).join('')||'<div class="tasks-empty">No tasks yet. Capture a clarification or record-request task after review.</div>'}</div></div>`}
function taskDialog(){modal(`<p class="modal-eyebrow">CLERICAL FOLLOW-THROUGH</p><h2>Add a task.</h2><p>Use a short administrative request. No external action will be taken.</p><form id="task-form"><label for="task-title">Task</label><input id="task-title" required maxlength="160" placeholder="e.g. Request the missing home log"><button type="submit" class="primary">Add local task</button></form>`);$('#task-form').addEventListener('submit',async ev=>{ev.preventDefault();const e=current(),title=$('#task-title').value.trim();if(!title)return;if(runtime.connected){try{Object.assign(e,await api('/api/encounters/'+e.id+'/tasks',{method:'POST',body:JSON.stringify({expected_revision:e.recordRevision,title})}));}catch(err){toast(err.message);return;}}else{e.tasks??=[];e.tasks.push({id:uid(),title,completed:false});}audit(e,'Reviewer added local clerical task');$('#modal').close();render();})}
function platform(){modal(`<p class="modal-eyebrow">PLATFORM & MODEL BOUNDARIES</p><h2>Connected modules. Explicit responsibilities.</h2><div class="module-list">${moduleRegistry.map(m=>`<article><h3>${esc(m.name)} <small>${esc(m.state)}</small></h3><p>${esc(m.scope)}</p><b>${esc(m.boundary)}</b></article>`).join('')}</div><p>${runtime.connected?'Local API and durable SQLite are connected. Reviewer authorization and version checks are enforced server-side.':'This private hosted preview uses browser-local demo data. The working local API/model backend runs separately on the laptop; it is not exposed through this Site.'}</p><p>Candidate language model: Qwen3.5 4B (Apache 2.0), restricted to exact source copying with code validation. No clinical fine-tuning has occurred. Local speech adapter: faster-whisper, small.en for a synthetic smoke fixture; real clinical audio still requires evaluation.</p><a href="MODEL_AND_SCALE_PLAN.md" target="_blank">Models, datasets, tuning and deployment plan ↗</a>`)}
